internal val SetupTemplate.label: StringResource
    get() = when (this) {
        SetupTemplate.BEGINNER -> Res.string.template_beginner
        SetupTemplate.ADVANCED -> Res.string.template_advanced
        SetupTemplate.PRO -> Res.string.template_pro
        SetupTemplate.TWO_VOICES -> Res.string.template_two_voices
    }

private val SetupTemplate.hint: StringResource
    get() = when (this) {
        SetupTemplate.BEGINNER -> Res.string.template_beginner_hint
        SetupTemplate.ADVANCED -> Res.string.template_advanced_hint
        SetupTemplate.PRO -> Res.string.template_pro_hint
        SetupTemplate.TWO_VOICES -> Res.string.template_two_voices_hint
    }

/**
 * The current setup on the Practice screen: its name, which switches setups (and makes new ones),
 * what its exercise is, and — on phones, where the settings are not beside it — "Adjust".
 */
@Composable
internal fun SetupCard(controller: AppController, onAdjust: (() -> Unit)?, modifier: Modifier = Modifier) {
    val settings = controller.settings
    Card(modifier.fillMaxWidth().padding(horizontal = SettingPadding, vertical = 8.dp)) {
        Column(Modifier.padding(start = 4.dp, end = 8.dp, top = 4.dp, bottom = 12.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Box(Modifier.weight(1f)) { SetupSwitcher(controller) }
                if (onAdjust != null) {
                    val description = stringResource(Res.string.customize_exercise)
                    TextButton(onClick = onAdjust, modifier = Modifier.semantics { contentDescription = description }) {
                        Icon(AppIcons.Tune, contentDescription = null, modifier = Modifier.size(18.dp))
                        Text(stringResource(Res.string.adjust), modifier = Modifier.padding(start = 8.dp))
                    }
                }
            }
            Text(
                stringResource(
                    Res.string.practice_summary,
                    modeLabel(settings.mode),
                    controller.noteName(settings.lowLimit),
                    controller.noteName(settings.highLimit),
                    settings.breathingTime.toString(),
                ) + " · " + stringResource(Res.string.setup_learned, controller.memoryCounts.sum()),
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.padding(horizontal = 12.dp),
            )
        }
    }
}

/** The setup's name; tapping it lists the setups to switch to and offers a new one. */
@Composable
private fun SetupSwitcher(controller: AppController) {
    var open by remember { mutableStateOf(false) }
    var newDialog by remember { mutableStateOf(false) }
    val description = stringResource(Res.string.setup_choose, controller.setupName)
    Box {
        TextButton(
            onClick = { open = true },
            enabled = !controller.running,
            modifier = Modifier.semantics { contentDescription = description },
        ) {
            Text(
                controller.setupName,
                style = MaterialTheme.typography.titleLarge,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = MaterialTheme.colorScheme.onSurface,
                modifier = Modifier.weight(1f, fill = false),
            )
            Icon(AppIcons.ArrowDropDown, contentDescription = null, tint = MaterialTheme.colorScheme.onSurface)
        }
        DropdownMenu(expanded = open, onDismissRequest = { open = false }) {
            controller.setupNames.forEach { name ->
                DropdownMenuItem(
                    text = { Text(name) },
                    leadingIcon = { if (name == controller.setupName) Icon(AppIcons.Check, contentDescription = null) },
                    onClick = {
                        open = false
                        controller.selectSetup(name)
                    },
                )
            }
            HorizontalDivider()
            DropdownMenuItem(
                text = { Text(stringResource(Res.string.setup_new)) },
                leadingIcon = { Icon(AppIcons.Add, contentDescription = null) },
                onClick = {
                    open = false
                    newDialog = true
                },
            )
        }
    }
    if (newDialog) NewSetupDialog(controller) { newDialog = false }
}

/**
 * The head of the setup's settings (sheet or side pane): its name, where it came from, and what
 * can be done with it as a whole.
 */
@Composable
internal fun SetupHeader(controller: AppController) {
    Row(
        verticalAlignment = Alignment.CenterVertically,
        modifier = Modifier.fillMaxWidth().padding(start = SettingPadding, end = 4.dp, top = 8.dp),
    ) {
        Text(
            controller.setupName,
            style = MaterialTheme.typography.titleLarge,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.weight(1f),
        )
        SetupMenu(controller)
    }
    val template = controller.setupTemplate
    SettingHint(
        if (template != null) {
            stringResource(Res.string.setup_from_template, stringResource(template.label))
        } else {
            stringResource(Res.string.setup_autosave)
        },
    )
}

@Composable
private fun SetupMenu(controller: AppController) {
    var menu by remember { mutableStateOf(false) }
    var dialog by remember { mutableStateOf<SetupDialog?>(null) }
    val template = controller.setupTemplate

    Box {
        IconButton(onClick = { menu = true }, enabled = !controller.running) {
            Icon(AppIcons.MoreVert, contentDescription = stringResource(Res.string.more_options))
        }
        DropdownMenu(expanded = menu, onDismissRequest = { menu = false }) {
            @Composable
            fun item(text: String, action: () -> Unit) = DropdownMenuItem(text = { Text(text) }, onClick = {
                menu = false
                action()
            })
            item(stringResource(Res.string.setup_rename)) { dialog = SetupDialog.RENAME }
            item(stringResource(Res.string.setup_copy)) { dialog = SetupDialog.COPY }
            if (template != null) item(stringResource(Res.string.setup_reset, stringResource(template.label))) { dialog = SetupDialog.RESET }
            if (controller.canExchangeSetups) {
                HorizontalDivider()
                item(stringResource(Res.string.setup_export)) { controller.exportSetup() }
                item(stringResource(Res.string.setup_import_file)) { controller.importSetup() }
            }
            if (controller.canImportLegacyFiles) item(stringResource(Res.string.setup_import)) { controller.importLegacySetup() }
            HorizontalDivider()
            item(stringResource(Res.string.setup_delete)) { dialog = SetupDialog.DELETE }
        }
    }

    val close = { dialog = null }
    when (dialog) {
        SetupDialog.RENAME -> NameDialog(
            title = stringResource(Res.string.setup_rename_title),
            initial = controller.setupName,
            confirm = stringResource(Res.string.save),
            onDismiss = close,
        ) { name, _ -> controller.renameSetup(name) }
        SetupDialog.COPY -> NameDialog(
            title = stringResource(Res.string.setup_copy_title),
            initial = stringResource(Res.string.setup_copy_name, controller.setupName),
            confirm = stringResource(Res.string.save),
            option = stringResource(Res.string.setup_copy_memory),
            onDismiss = close,
        ) { name, withMemory -> controller.copySetup(name, withMemory) }
        SetupDialog.RESET -> if (template != null) {
            val name = stringResource(template.label)
            ConfirmDialog(
                title = stringResource(Res.string.setup_reset_title, name),
                text = stringResource(Res.string.setup_reset_text),
                confirm = stringResource(Res.string.reset),
                onDismiss = close,
                onConfirm = controller::resetToTemplate,
            )
        }
        SetupDialog.DELETE -> ConfirmDialog(
            title = stringResource(Res.string.setup_delete_title, controller.setupName),
            text = stringResource(Res.string.setup_delete_text),
            confirm = stringResource(Res.string.delete),
            destructive = true,
            onDismiss = close,
            onConfirm = controller::deleteCurrentSetup,
        )
        null -> Unit
    }
}

private enum class SetupDialog { RENAME, COPY, RESET, DELETE }

/** A name for a new setup and the template it starts from. */
@Composable
private fun NewSetupDialog(controller: AppController, onDismiss: () -> Unit) {
    var template by remember { mutableStateOf(SetupTemplate.BEGINNER) }
    val templateName = stringResource(template.label)
    // The name follows the template until the player types one of their own.
    var name by remember { mutableStateOf<String?>(null) }
    val shownName = name ?: templateName
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(Res.string.setup_new_title)) },
        text = {
            Column(Modifier.verticalScroll(rememberScrollState())) {
                OutlinedTextField(
                    value = shownName,
                    onValueChange = { name = it },
                    label = { Text(stringResource(Res.string.setup_name)) },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                )
                Text(
                    stringResource(Res.string.setup_template),
                    style = MaterialTheme.typography.titleSmall,
                    color = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.padding(top = 16.dp, bottom = 4.dp),
                )
                Column(Modifier.selectableGroup()) {
                    SetupTemplate.entries.forEach { option ->
                        ListItem(
                            headlineContent = { Text(stringResource(option.label)) },
                            supportingContent = { Text(stringResource(option.hint)) },
                            leadingContent = { RadioButton(selected = option == template, onClick = null) },
                            colors = itemColors(),
                            modifier = Modifier.selectable(selected = option == template, role = Role.RadioButton) { template = option },
                        )
                    }
                }
            }
        },
        confirmButton = {
            TextButton(enabled = shownName.isNotBlank(), onClick = {
                onDismiss()
                controller.createSetup(shownName, template)
            }) { Text(stringResource(Res.string.save)) }
        },
        dismissButton = { TextButton(onClick = onDismiss) { Text(stringResource(Res.string.cancel)) } },
    )
}

/** Asks for a name, and with [option] for one yes or no (off at first). */
@Composable
private fun NameDialog(
    title: String,
    initial: String,
    confirm: String,
    onDismiss: () -> Unit,
    option: String? = null,
    onConfirm: (name: String, option: Boolean) -> Unit,
) {
    var name by remember { mutableStateOf(initial) }
    var checked by remember { mutableStateOf(false) }
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(title) },
        text = {
            Column {
                OutlinedTextField(value = name, onValueChange = { name = it }, label = { Text(stringResource(Res.string.setup_name)) }, singleLine = true)
                if (option != null) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier.padding(top = 12.dp).toggleable(value = checked, role = Role.Checkbox) { checked = it },
                    ) {
                        Checkbox(checked = checked, onCheckedChange = null)
                        Text(option, modifier = Modifier.padding(start = 12.dp))
                    }
                }
            }
        },
        confirmButton = {
            TextButton(enabled = name.isNotBlank(), onClick = {
                onDismiss()
                onConfirm(name, checked)
            }) { Text(confirm) }
        },
        dismissButton = { TextButton(onClick = onDismiss) { Text(stringResource(Res.string.cancel)) } },
    )
}

@Composable
private fun ConfirmDialog(
    title: String,
    text: String,
    confirm: String,
    onDismiss: () -> Unit,
    onConfirm: () -> Unit,
    destructive: Boolean = false,
) {
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(title) },
        text = { Text(text) },
        confirmButton = {
            TextButton(onClick = {
                onDismiss()
                onConfirm()
            }) { Text(confirm, color = if (destructive) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary) }
        },
        dismissButton = { TextButton(onClick = onDismiss) { Text(stringResource(Res.string.cancel)) } },
    )
}
